E=[]
def add(title,q,steps,answer,kind,**kw):
 E.append(dict(id=len(E)+1,title=title,q=q,steps=steps,answer=answer,kind=kind,**kw))
add('Do gelo a −20 °C ao vapor a 130 °C',r'Qual a quantidade de calor, em kcal, necessária para que 1 L de água congelada a −20 °C vaporize totalmente e chegue a 130 °C? Adote 1 L de água = 1000 g. Dados: $L_f=80\,\mathrm{cal/g}$, $L_v=540\,\mathrm{cal/g}$, $c_g=0{,}5\,\mathrm{cal/(g\cdot{}^\circ C)}$ e $c_v=0{,}48\,\mathrm{cal/(g\cdot{}^\circ C)}$.',[
r'Aqueça o gelo até 0 °C: $Q_1=mc_g\Delta T=1000\cdot0{,}5\cdot20=10000\,\mathrm{cal}$.',
r'Derreta o gelo a 0 °C: $Q_2=mL_f=1000\cdot80=80000\,\mathrm{cal}$. A temperatura fica constante.',
r'Aqueça a água até 100 °C: $Q_3=1000\cdot1\cdot100=100000\,\mathrm{cal}$.',
r'Vaporize a água a 100 °C: $Q_4=mL_v=1000\cdot540=540000\,\mathrm{cal}$.',
r'Aqueça o vapor até 130 °C: $Q_5=1000\cdot0{,}48\cdot30=14400\,\mathrm{cal}$.',
r'$Q=10000+80000+100000+540000+14400=744400\,\mathrm{cal}=744{,}4\,\mathrm{kcal}$.'],r'$Q=744{,}4\,\mathrm{kcal}$','thermal',mass=1000,temps=[-20,0,0,100,100,130],heats=[10000,80000,100000,540000,14400],phases=['Gelo aquecendo','Fusão: gelo → água','Água aquecendo','Vaporização: água → vapor','Vapor aquecendo'],states=[['Gelo','Gelo'],['Gelo','Água'],['Água','Água'],['Água','Vapor'],['Vapor','Vapor']],sign=1,note='O PDF não informa o calor específico da água líquida nesta questão. Usamos 1 cal/(g·°C), como nas demais questões. As mudanças a 0 °C e 100 °C pressupõem pressão atmosférica normal.')
add('Curva de aquecimento de 400 g',r'Temos 400 g de gelo a −20 °C. Determine o calor que essa massa deve receber para se transformar em 400 g de água líquida a 20 °C e trace a curva de aquecimento. Dados: $c_g=0{,}5\,\mathrm{cal/(g\cdot{}^\circ C)}$, $c_a=1{,}0\,\mathrm{cal/(g\cdot{}^\circ C)}$ e $L_f=80\,\mathrm{cal/g}$.',[
r'Até 0 °C: $Q_1=400\cdot0{,}5\cdot20=4000\,\mathrm{cal}$.',r'Na fusão: $Q_2=400\cdot80=32000\,\mathrm{cal}$. A temperatura permanece em 0 °C.',r'Até 20 °C: $Q_3=400\cdot1\cdot20=8000\,\mathrm{cal}$.',r'$Q=4000+32000+8000=44000\,\mathrm{cal}$. A curva passa por $(0,-20)$, $(4,0)$, $(36,0)$ e $(44,20)$, com Q em kcal e T em °C.'],r'$Q=44000\,\mathrm{cal}$','thermal',mass=400,temps=[-20,0,0,20],heats=[4000,32000,8000],phases=['Gelo aquecendo','Fusão: gelo → água','Água aquecendo'],states=[['Gelo','Gelo'],['Gelo','Água'],['Água','Água']],sign=1)
add('Curva de aquecimento de 100 g',r'Quantas calorias são necessárias para transformar 100 g de gelo a −10 °C em água a 50 °C? O gelo funde a 0 °C. Dados: $c_g=0{,}5\,\mathrm{cal/(g\cdot{}^\circ C)}$, $L_f=80\,\mathrm{cal/g}$ e $c_a=1{,}0\,\mathrm{cal/(g\cdot{}^\circ C)}$. Construa a curva de aquecimento.',[
r'Aqueça o gelo: $Q_1=100\cdot0{,}5\cdot10=500\,\mathrm{cal}$.',r'Funda o gelo: $Q_2=100\cdot80=8000\,\mathrm{cal}$.',r'Aqueça a água: $Q_3=100\cdot1\cdot50=5000\,\mathrm{cal}$.',r'$Q=500+8000+5000=13500\,\mathrm{cal}$. A curva passa por $(0,-10)$, $(0{,}5,0)$, $(8{,}5,0)$ e $(13{,}5,50)$, com Q em kcal.'],r'$Q=13500\,\mathrm{cal}$','thermal',mass=100,temps=[-10,0,0,50],heats=[500,8000,5000],phases=['Gelo aquecendo','Fusão: gelo → água','Água aquecendo'],states=[['Gelo','Gelo'],['Gelo','Água'],['Água','Água']],sign=1)
add('Do vapor a 130 °C à água a 50 °C',r'Temos 100 g de vapor de água a 130 °C. Qual é o calor que deve ser perdido para transformar esse vapor em 100 g de água líquida a 50 °C? O vapor condensa a 100 °C, com $L_C=-540\,\mathrm{cal/g}$. Use $c_v=0{,}48\,\mathrm{cal/(g\cdot{}^\circ C)}$ e $c_a=1{,}0\,\mathrm{cal/(g\cdot{}^\circ C)}$.',[
r'Resfrie o vapor: $Q_1=100\cdot0{,}48\cdot(100-130)=-1440\,\mathrm{cal}$.',r'Condense a 100 °C: $Q_2=100\cdot(-540)=-54000\,\mathrm{cal}$.',r'Resfrie a água: $Q_3=100\cdot1\cdot(50-100)=-5000\,\mathrm{cal}$.',r'$Q=-1440-54000-5000=-60440\,\mathrm{cal}$. O sinal negativo indica que a amostra cede calor: é preciso retirar 60440 cal.'],r'$Q=-60440\,\mathrm{cal}$; calor retirado: $60440\,\mathrm{cal}$.','thermal',mass=100,temps=[130,100,100,50],heats=[1440,54000,5000],phases=['Vapor resfriando','Condensação: vapor → água','Água resfriando'],states=[['Vapor','Vapor'],['Vapor','Água'],['Água','Água']],sign=-1)
add('Gelo derretendo em equilíbrio',r'(UNICAMP–SP) Icebergs flutuam na água do mar, assim como o gelo em um copo com água potável. Considere inicialmente água e gelo em equilíbrio térmico a 0 °C. Com o passar do tempo, o gelo derrete. Enquanto houver gelo, a temperatura do sistema:',[
r'Enquanto gelo e água coexistem em equilíbrio durante a fusão, o calor recebido é usado na mudança de fase: a temperatura permanece em 0 °C.',r'Para a mesma massa, o gelo ocupa mais volume do que a água líquida, pois sua densidade é menor.',r'Ao derreter, o volume material total de gelo + água diminui. Alternativa B.',r'Isso não significa que o nível da água no copo baixe: com gelo flutuante em água doce, sem derramamento, o nível permanece praticamente constante.'],r'Alternativa B: temperatura constante e volume material total menor.','melt',choices=['permanece constante, mas o volume do sistema aumenta.','permanece constante, mas o volume do sistema diminui.','diminui e o volume do sistema aumenta.','diminui, assim como o volume do sistema.'],note='A visualização de volume usa uma amostra ilustrativa de 100 g e densidades aproximadas de 0,917 g/cm³ para o gelo e 1 g/cm³ para a água. Não representa a altura da água no copo.')
add('A bolinha que abandona a mesa',r'Uma bolinha rola a 5 m/s sobre uma mesa horizontal de altura 1,25 m e abandona a borda com essa velocidade. Adote $g=10\,\mathrm{m/s^2}$ e despreze a resistência do ar.',[
r'a) Na horizontal, $x=v_0t$; na vertical, $y=h-gt^2/2$. Eliminando t: $y=h-\frac{g}{2v_0^2}x^2$. A trajetória é um arco de parábola.',r'b) Ao tocar o chão, $0=1{,}25-5t^2$, portanto $t=0{,}5\,\mathrm{s}$.',r'c) $x=5\cdot0{,}5=2{,}5\,\mathrm{m}$.',r'd) O tempo é igual ao de uma bolinha apenas abandonada: ambas têm velocidade vertical inicial zero, a mesma altura e a mesma aceleração vertical.',r'e) $v_x=5\,\mathrm{m/s}$ e $|v_y|=gt=5\,\mathrm{m/s}$. Logo, $v=\sqrt{5^2+5^2}=5\sqrt2\approx7{,}07\,\mathrm{m/s}$.'],r'$t=0{,}5\,\mathrm{s}$; alcance $2{,}5\,\mathrm{m}$; velocidade final $5\sqrt2\,\mathrm{m/s}$.','launch',h=1.25,vx=5,g=10,parts=['a) Desenhe a trajetória em relação ao solo.','b) Em quanto tempo a bolinha chega ao chão?','c) Calcule o deslocamento horizontal até tocar o chão.','d) Esse tempo seria maior, menor ou igual se a bolinha fosse apenas abandonada da borda? Por quê?','e) Calcule o módulo da velocidade ao chegar ao chão.'])
add('Duas pedras, a mesma queda',r'No instante t=0, uma pedra A é abandonada do repouso de uma altura de 80 m. Simultaneamente, uma pedra B é lançada horizontalmente a 30 m/s da mesma altura. Despreze o ar e adote $g=10\,\mathrm{m/s^2}$.',[
r'a) Para A: $80=gt^2/2=5t^2$. Assim, $t=4\,\mathrm{s}$.',r'b) B tem o mesmo movimento vertical e o mesmo tempo de queda. Sua distância horizontal é $d=30\cdot4=120\,\mathrm{m}$.',r'c) A chega ao solo com velocidade vertical de módulo $v_A=gt=40\,\mathrm{m/s}$.',r'd) Em B: $v_x=30\,\mathrm{m/s}$ e $|v_y|=40\,\mathrm{m/s}$, para baixo. As componentes são perpendiculares; como conferência, o módulo total de B é 50 m/s.'],r'$t=4\,\mathrm{s}$; $d=120\,\mathrm{m}$; $v_A=40\,\mathrm{m/s}$; $v_{Bx}=30\,\mathrm{m/s}$ e $|v_{By}|=40\,\mathrm{m/s}$.','launch',h=80,vx=30,g=10,parts=['a) Calcule o instante em que A chega ao chão.','b) Calcule a distância horizontal percorrida por B até o chão.','c) Calcule o módulo da velocidade de A imediatamente antes do impacto.','d) Determine os módulos das componentes horizontal e vertical da velocidade de B imediatamente antes do impacto.'])
add('Corrida para alcançar a bola',r'Dois rapazes brincam de tênis na praia. Um deles rebate a bola horizontalmente, a 2,45 m de altura, com velocidade de 72 km/h. O outro está inicialmente 20,3 m à frente do primeiro. Qual deve ser sua velocidade mínima para aparar a bola antes que ela bata na areia? Adote $g=10\,\mathrm{m/s^2}$.',[
r'Converta a velocidade da bola: $72/3{,}6=20\,\mathrm{m/s}$.',r'O tempo até a areia é $t=\sqrt{2h/g}=\sqrt{4{,}9/10}=0{,}7\,\mathrm{s}$.',r'A bola alcança $x=20\cdot0{,}7=14\,\mathrm{m}$. O segundo rapaz precisa correr $20{,}3-14=6{,}3\,\mathrm{m}$ em direção ao primeiro.',r'O valor-limite é $u=6{,}3/0{,}7=9\,\mathrm{m/s}$, resposta do gabarito.',r'No modelo ideal, exatamente 9 m/s faz o encontro ocorrer no instante do contato com a areia. Para interceptar estritamente antes, é necessário $u>9\,\mathrm{m/s}$. A simulação mostra essa diferença.'],r'$9\,\mathrm{m/s}$ é o valor-limite; para encontro acima da areia, $u>9\,\mathrm{m/s}$.','tennis',h=2.45,vx=20,g=10,distance=20.3,note='Modelo do exercício: corrida uniforme iniciada junto com a raquetada, sem tempo de reação, bola pontual e altura de recepção não especificada.')
assert len(E)==8
